"""Plan the slope from the chunks actually generated by the ordinary 1.21.1 survival client."""
from collections import deque
from functools import lru_cache
from pathlib import Path
import json
import sys
here=Path(__file__).resolve().parent
play=here.parent/'play'
sys.path.insert(0,str(here.parents[2]/'reports/2026-11-21-rain-eaves/fixture'))
from anvil import World
identity=json.loads((play/'baseline-170-r1/identity.json').read_text())
w=World(Path(identity['world']))
src=json.loads((play/'route-plan.json').read_text())
def kind(x,y,z):return (w.block(x,y,z) or 'unknown').split('[')[0].split(':')[-1]
air={'air','cave_air','short_grass','tall_grass','fern','poppy','red_mushroom','brown_mushroom','dandelion','allium','cornflower','glow_lichen','large_fern','oxeye_daisy','azure_bluet'}
@lru_cache(maxsize=None)
def stand(x,y,z):
    floor=kind(x,y-1,z)
    return (kind(x,y,z) in air and kind(x,y+1,z) in air and floor not in air|{'unknown','lava','water'}
            and not floor.endswith(('leaves','torch','fence','wall','flower')))
def path(source,target):
    a=tuple(source);b=tuple(target)
    assert stand(*a) and stand(*b),(a,b)
    parent={a:None};queue=deque([a])
    while queue:
        p=queue.popleft()
        if p==b:
            steps=[]
            while p:
                steps.append(p);p=parent[p]
            return steps[::-1]
        x,y,z=p
        for dx,dz in ((1,0),(0,1),(-1,0),(0,-1)):
            for dy in (0,1,-1):
                q=(x+dx,y+dy,z+dz)
                if not (548<q[0]<607 and 406<q[2]<443) or not stand(*q):continue
                if dy>0 and kind(x,y+2,z) not in air:continue
                if q not in parent:parent[q]=p;queue.append(q)
                break
    raise RuntimeError('No connected stance path through generated terrain')
def waypoints(nodes):
    # Preserve cardinal turns. Merge only straight runs with the same slope.
    points=[nodes[0]]
    for i in range(1,len(nodes)-1):
        a,b,c=nodes[i-1:i+2]
        if tuple(y-x for x,y in zip(a,b))!=tuple(y-x for x,y in zip(b,c)) or max(abs(x-y) for x,y in zip(points[-1],b))>=5:
            points.append(b)
    points.append(nodes[-1])
    return [[x+.5,y,z+.5] for x,y,z in points]
for a,b in (('water','cave'),('cave','spawn')):
    seq=path(src['keys'][a],src['keys'][b])
    src['legs'][a+'->'+b]=dict(cells=len(seq),waypoints=waypoints(seq))
src['actualGeneratedWorld']=identity['world']
(here/'final-route.json').write_text(json.dumps(src,indent=2))
print([(k,v['cells'],len(v['waypoints'])) for k,v in src['legs'].items() if 'cave' in k])
